def coeffs(poly):
    return list(map(int, poly.coeffs()))


def geometry_bound(p, n, b):
    """A tame S_n Galois closure with simple finite branches and infinity pole s.

    2g-2=n!*(-2+r/2+1-1/s); twisting by an n-cycle gives n rational
    points per unramified irreducible fiber. Ramified fibers cost <=(r+1)n!.
    This function does NOT establish the Morse hypotheses; caller must do so.
    """
    if type(p) is not int or not fmpz(p).is_prime():
        raise ValueError("a prime characteristic is required")
    if (type(n) is not int or type(b) is not int or n < 4 or n % 2 or b < 1
            or n - b < 3 or p <= n + b - 1):
        raise ValueError("even degree>=4, positive modulus, slack>=3 and large tame characteristic required")
    h, r, s = math.factorial(n), n + b - 1, n - b
    twice_genus_minus_two = r * (h // 2) - h - h // s
    if twice_genus_minus_two % 2:
        raise ArithmeticError("Galois-closure genus is not integral")
    genus = 1 + twice_genus_minus_two // 2
    root = math.isqrt(p)
    upper_sqrt = root if root * root == p else root + 1
    branch_count = r + 1
    numerator = p + 1 - 2 * genus * upper_sqrt - branch_count * h
    probability = max(Fraction(0), Fraction(numerator, n * p))
    bad_degree = (2 * r - 2) * (n + r + 1)
    geometry_probability = max(Fraction(0), Fraction(p - bad_degree, p))
    threshold = max(64 * genus * genus, 4 * branch_count * h, 2 * bad_degree)
    return {"cover_degree": n, "modulus_degree": b, "finite_simple_branch_count": r,
            "infinity_pole_order": s, "Galois_group_order_decimal": str(fmpz(h)),
            "Galois_closure_genus_decimal": str(fmpz(genus)), "branch_point_count": branch_count,
            "sqrt_p_upper_integer": str(upper_sqrt),
            "irreducible_fiber_probability_lower_exact": str(fmpq(probability.numerator, probability.denominator)),
            "sufficient_p_for_probability_at_least_1_over_2n_decimal": str(fmpz(threshold)),
            "field_meets_sufficient_threshold": p >= threshold,
            "generic_Morse_bad_parameter_degree_upper": bad_degree,
            "generic_Morse_pair_probability_lower_under_local_discriminant_proof": str(
                fmpq(geometry_probability.numerator, geometry_probability.denominator)),
            "generic_argument_uses_Bank_BarySoroker_Rosenzweig_lemmas_3_4_3_5": True,
            "no_Galois_group_or_factorial_degree_extension_enumerated": True,
            "this_bound_alone_verifies_the_Morse_hypotheses": False}


def morse_certificate(p, f, g, *, bound_method="twist"):
    """Check ALL algebraic critical points/values by exact gcds and resultant.

    The critical-value resultant has degree r=n+b-1 in Y. Interpolation from
    r+1 exact scalar resultants is polynomial-size, not a p-entry field scan.
    """
    C = ring(p)
    n, b = f.degree(), g.degree()
    bound = geometry_bound(p, n, b)
    if bound_method not in ("twist", "exterior"):
        raise ValueError("bound_method must be twist or exterior")
    if bound_method == "exterior":
        from qsearch_classical.prime_character_exterior_bound import exterior_bound
        bound = exterior_bound(p, n, b)
    if int(f.leading_coefficient()) != 1 or int(g.leading_coefficient()) != 1:
        raise ValueError("monic rational-map numerator and denominator required")
    if f.gcd(g).degree() != 0 or g.gcd(g.derivative()).degree() != 0:
        raise ValueError("coprime numerator and squarefree denominator required")
    W = f.derivative() * g - f * g.derivative()
    r = bound["finite_simple_branch_count"]
    common = {"p_decimal": str(p), "f_coefficients": coeffs(f), "g_coefficients": coeffs(g),
              "critical_numerator_coefficients": coeffs(W), "arithmetic_bound": bound,
              "local_geometry_and_twist_derivation_review_pending": True}
    if W.degree() != r or W.gcd(g).degree() != 0:
        raise ArithmeticError("critical numerator lost the expected tame pole profile")
    if W.gcd(W.derivative()).degree() != 0:
        return {**common, "status": "NON_MORSE_REPEATED_CRITICAL_POINT", "Morse_conditions_verified": False}
    values = [int(W.resultant(f - y * g)) for y in range(r + 1)]
    B, _ = interpolate(p, tuple(range(r + 1)), tuple(values))
    if B.degree() != r:
        raise ArithmeticError("critical-value resultant degree is inconsistent")
    # A fresh scalar specialization checks the reconstructed resultant too.
    probe = r + 1 if r + 1 < p else p - 1
    if int(B(probe)) != int(W.resultant(f - probe * g)):
        raise ArithmeticError("critical-value resultant failed independent specialization")
    B *= pow(int(B.leading_coefficient()), -1, p)
    common.update({"critical_value_polynomial_coefficients": coeffs(B),
                   "critical_resultant_samples": values, "critical_resultant_evaluations_charged": r + 2,
                   "full_field_table_materialized": False})
    if B.gcd(B.derivative()).degree() != 0:
        return {**common, "status": "NON_MORSE_COLLIDING_CRITICAL_VALUES", "Morse_conditions_verified": False}
    return {**common, "status": "EXACT_TAME_MORSE_CONDITIONS_VERIFIED", "Morse_conditions_verified": True,
            "geometric_monodromy_conclusion_under_stated_proof": "S_n",
            "fixed_input_probability_bound_available": Fraction(bound["irreducible_fiber_probability_lower_exact"]) > 0,
            "independent_or_formal_proof_review_completed": False}


def prepare(problem):
    """Use the majority coset first, avoid nonunit residue values deterministically."""
    if problem.exponent != 2 or len(set(problem.orientations)) != 2:
        return {"status": "NOT_APPLICABLE_TWO_QUADRATIC_COSETS_REQUIRED"}, None
    p, K, C = problem.prime, problem.dimension, ring(problem.prime)
    first = max((0, 1), key=lambda o: problem.orientations.count(o))
    A = tuple(i for i, o in enumerate(problem.orientations) if o == first)
    B = tuple(i for i, o in enumerate(problem.orientations) if o != first)
    n = 2 * ((K - 1) // 2)
    data = {"specification": problem.specification(), "first_orientation": first,
            "A_positions": list(A), "B_positions": list(B), "norm_target_degree": n,
            "local_reduction_review_pending": True}
    if len(A) >= K or n < 4 or n - len(B) < 3 or p <= max(n + len(B) - 1, 2 * problem.length):
        return {**data, "status": "NOT_APPLICABLE_DEGREE_SLACK_OR_CHARACTERISTIC",
                "original_problem_unsatisfiability_claimed": False}, None
    beta = pow(problem.coset_generator, first, p)
    nu = pow(problem.coset_generator, 1 - first, p) * pow(beta, -1, p) % p
    T, V_A = interpolate(p, tuple(i + 1 for i in A), tuple(problem.shifts[i] for i in A))
    forbidden = {(problem.shifts[i] - int(T(i + 1))) * pow(int(V_A(i + 1)), -1, p) % p for i in B}
    shift = next(a for a in range(len(B) + 1) if a not in forbidden)
    Q0 = T + shift * V_A
    f0, g = interpolate(p, tuple(i + 1 for i in B),
                        tuple((problem.shifts[i] - int(Q0(i + 1))) * pow(beta, -1, p) % p for i in B))
    if f0.gcd(g).degree() != 0:
        raise ArithmeticError("deterministic public shift did not make the residue a unit")
    base = f0 + g * C.gen() ** (n - len(B))
    return {**data, "status": "EXACT_UNIT_ARITHMETIC_PROGRESSION_PREPARED",
            "beta_decimal": str(beta), "nu_decimal": str(nu), "interpolation_shift": shift,
            "forbidden_shift_count": len(forbidden), "Q0_coefficients": coeffs(Q0),
            "residue_coefficients": coeffs(f0), "modulus_coefficients": coeffs(g),
            "base_numerator_coefficients": coeffs(base), "arithmetic_bound": geometry_bound(p, n, len(B))}, (base, g, Q0, beta, nu)


def attack(problem, seed=0, *, geometry_trials=16, fiber_trials=128, bound_method="twist"):
    if bound_method not in ("twist", "exterior"):
        raise ValueError("bound_method must be twist or exterior")
    integer(geometry_trials, "public geometry trial cap", 1, 4096)
    integer(fiber_trials, "public fiber trial cap", 1, 4096)
    if seed is not None:
        integer(seed, "public replay seed", 0, (1 << 64) - 1)
    prepared, state = prepare(problem)
    if state is None:
        return prepared
    p, C = problem.prime, ring(problem.prime)
    base, g, Q0, beta, nu = state
    rng = random.SystemRandom() if seed is None else random.Random(seed)
    geometries, certificate = [], None
    for _ in range(geometry_trials):
        a1, a2 = rng.randrange(p), rng.randrange(p)
        f = base + g * C([0, a1, a2])
        candidate = morse_certificate(p, f, g, bound_method=bound_method)
        geometries.append({"a1_decimal": str(a1), "a2_decimal": str(a2), "certificate": candidate})
        if candidate["Morse_conditions_verified"]:
            certificate = candidate
            break
    result = {"preparation": prepared, "geometry_attempts": geometries, "seed": seed,
              "source_rerolled_or_rejected": False,
              "randomness_policy": "system_uniform_bits_assumed" if seed is None else "seeded_replay_not_an_IID_certificate",
              "local_proof_review_pending": True, "accepted_speedup_candidate": False}
    if bound_method != "twist":
        result["fiber_bound_method"] = bound_method
    if certificate is None:
        return {**result, "status": "NO_MORSE_CERTIFICATE_WITHIN_BUDGET_UNKNOWN"}
    if not certificate["fixed_input_probability_bound_available"]:
        return {**result, "status": "MORSE_CERTIFIED_FIELD_TOO_SMALL_FOR_THIS_EXPLICIT_BOUND",
                "small_field_failure_is_not_hardness": True}
    fibers = []
    for index in range(fiber_trials):
        value = rng.randrange(p)
        F = f - value * g
        is_irreducible = F.is_irreducible()
        record = {"index": index, "fiber_parameter_decimal": str(value), "irreducible": is_irreducible}
        fibers.append(record)
        if not is_irreducible:
            continue
        norm = polynomial_norm(p, nu, F)
        R, Z = C(norm["R_coefficients"]), C(norm["Z_coefficients"])
        rotation = None
        if not problem.include_zero:
            R, Z, rotation = strict_norm_rotation(problem, R, Z, F, nu,
                                                 first_orientation=prepared["first_orientation"])
            if R is None:
                raise ArithmeticError("irreducible target did not permit strict zero avoidance")
        Q = Q0 + beta * R ** 2
        coefficients = tuple(coeffs(Q))
        if Q.degree() >= problem.dimension or problem.score_count(coefficients) != problem.length:
            raise ArithmeticError("native Horner verifier rejected the certified norm witness")
        record.update({"norm_certificate": norm, "strict_rotation": rotation,
                       "target_F_coefficients": coeffs(F), "Q_coefficients": list(coefficients)})
        return {**result, "status": "CLASSICAL_PERFECT_WITNESS_WITH_FIXED_INPUT_GEOMETRIC_BOUND",
                "fiber_attempts": fibers, "polynomial_coefficients": list(coefficients),
                "native_score": problem.length,
                "probability_lower_bound_under_local_geometry_proof": certificate["arithmetic_bound"]["irreducible_fiber_probability_lower_exact"],
                "geometry_and_fiber_costs_include_failed_trials": True}
    return {**result, "status": "NO_IRREDUCIBLE_FIBER_WITHIN_BUDGET_UNKNOWN", "fiber_attempts": fibers,
            "budget_exhaustion_is_not_unsatisfiability": True}


def quartic_control():
    """Exact S4 curve control: r=X^3+1/X, not an OPI research candidate."""
    p, C = 10007, ring(10007)
    f, g = C([1, 0, 0, 0, 1]), C([0, 1])
    certificate = morse_certificate(p, f, g)
    actual = sum((f - value * g).is_irreducible() for value in range(p))
    bound = Fraction(certificate["arithmetic_bound"]["irreducible_fiber_probability_lower_exact"])
    if Fraction(actual, p) < bound:
        raise ArithmeticError("complete quartic fiber count violates the proposed bound")
    return {"certificate": certificate, "all_fibers_enumerated_and_charged": p,
            "actual_irreducible_fibers": actual,
            "this_full_field_calibration_is_not_the_large_input_algorithm": True}


def large_field_lift_control():
    """A declared new field, not a replacement for the original 61-bit input.

    Keep all127 shifts and orientations. Only p and its verified nonsquare
    change; this deliberately fixed source requires no IID-shift assumption.
    """
    original = instance(2 ** 61 - 1, 127, 77, 2, 29, mode="mixed", include_zero=False)
    p = 2 ** 1279 - 1
    nonsquare = next(g for g in range(2, 258) if pow(g, (p - 1) // 2, p) == p - 1)
    lifted = PrimeCharacterOPI(p, original.dimension, 2, nonsquare, original.shifts,
                               original.orientations, nonsquare - 1, include_zero=False)
    n = 2 * ((lifted.dimension - 1) // 2)
    failure_bits = 10
    budget = 2 * n * (failure_bits + 1)
    record = attack(lifted, 4301, fiber_trials=budget)
    return {"original_specification": original.specification(), "lifted_fixed_input_attack": record,
            "only_field_and_verified_nonsquare_changed": True,
            "is_the_original_61_bit_problem": False, "new_field_prime_checked_by_FLINT": True,
            "uniform_fiber_failure_budget_bits": failure_bits, "fiber_trial_budget": budget,
            "probability_model_requires_independent_uniform_fibers": True,
            "seeded_run_is_not_an_IID_confidence_certificate": True}


def run_controls():
    small = [attack(instance(2 ** 61 - 1, 15, 12, 2, seed, mode="mixed", include_zero=include_zero), seed + 3011)
             for seed in (29, 71) for include_zero in (True, False)]
    large = [attack(instance(2 ** 61 - 1, 127, 77, 2, seed, mode="mixed"), seed + 3011)
             for seed in (29, 71)]
    return {"schema_version": "prime-character-morse-attack-v1", "native_controls": small,
            "larger_field_size_guard_controls": large, "exact_quartic_control": quartic_control(),
            "large_field_fixed_input_control": large_field_lift_control(),
            "source_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
            "dependency_sha256": {name: hashlib.sha256((PACKAGE/_vendored(name)).read_bytes()).hexdigest()
                                  for name in ("prime_character_opi.py", "prime_character_norm_attack.py")},
            "literature": ["https://arxiv.org/html/1302.0625"],
            "fixed_degree_asymptotic_used_as_a_uniform_bound": False,
            "all_input_or_all_field_dequantization_claimed": False,
            "independent_or_formal_proof_review_completed": False,
            "new_central_candidate_negative_or_proof_registered": False}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--write", action="store_true")
    args = parser.parse_args()
    report = run_controls()
    if args.write:
        REPORT.write_text(json.dumps(report, indent=2, allow_nan=False) + "\n")
    print(json.dumps({"native": [{"status": r["status"], "score": r.get("native_score"),
                                  "fiber_trials": len(r.get("fiber_attempts", [])),
                                  "probability_lower": r.get("probability_lower_bound_under_local_geometry_proof")}
                                 for r in report["native_controls"]],
                      "larger_field_guard": [r["status"] for r in report["larger_field_size_guard_controls"]],
                      "large_field_fixed_input": {"status": report["large_field_fixed_input_control"]["lifted_fixed_input_attack"]["status"],
                                                  "score": report["large_field_fixed_input_control"]["lifted_fixed_input_attack"].get("native_score"),
                                                  "fibers": len(report["large_field_fixed_input_control"]["lifted_fixed_input_attack"].get("fiber_attempts", []))},
                      "quartic_irreducibles": report["exact_quartic_control"]["actual_irreducible_fibers"]}, indent=2))


if __name__ == "__main__":
    main()
